{
    // Define the half-size of the rectangle in UV space.
    // This assumes the rectangle is aligned with the UV axes.
    float2 half = halfSize;

    // Calculate the distance from the center of the rectangle to the point.
    float2 center = float2(0.5, 0.5);
    float2 distFromCenter = abs(uv - center) - half;

    // Check if the point is inside the rectangle.
    float inside = step(0, min(distFromCenter.x, distFromCenter.y));

    // If inside, return 0 as the distance is 0.
    float outsideDistance = max(distFromCenter.x, distFromCenter.y);

    // Return the signed distance: positive outside, negative inside.
    return -inside * outsideDistance;
}

// Example usage:
